import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());

        final long MOD = 1000000007L;
        int[][] near = {{4, 6}, {6, 8}, {7, 9}, {4, 8}, {0, 3, 9}, {}, {0, 1, 7}, {2, 6}, {1, 3}, {2, 4}};
        long[] count = new long[10];
        Arrays.fill(count, 1);
        long[] next = new long[10];
        for (long step = 1; step < n; step++) {
            for (int d = 0; d < 10; d++) {
                long sum = 0;
                for (int e : near[d]) sum += count[e];
                next[d] = sum % MOD;
            }
            long[] swap = count;
            count = next;
            next = swap;
        }
        long total = 0;
        for (int d = 0; d < 10; d++) total += count[d];
        System.out.println(total % MOD);
    }
}
